// Helper to deeply clone and substitute translations
function createLocaleDict(overrides: Record<string, any>): any {
  function apply(base: any, over: any): any {
    if (typeof base === 'object' && base !== null && !Array.isArray(base)) {
      const res: Record<string, any> = {};
      for (const [k, v] of Object.entries(base)) {
        res[k] = apply(v, over ? over[k] : undefined);
      }
      return res;
    }
    return over !== undefined ? over : base;
  }
  return apply(en, overrides);
}

